    Array.isArray($json.Lista) ? $json.Lista : ($json.Lista ? [$json.Lista] : [])
  ).map(i => {
    let s = i;

    if (s && typeof s === 'object') {
      s = typeof s.message_user === 'string' ? s.message_user : JSON.stringify(s);
    } else if (typeof s === 'string') {
      try {
        const p = JSON.parse(s);
        if (p && typeof p.message_user === 'string') s = p.message_user;
        else if (typeof p === 'string') s = p;
      } catch {}
    } else {
      s = String(s ?? '');
    }

    return String(s)
      .replace(/\\n/g, ' ')                    // quebra de linha -> espaço
      .replace(/\\"/g, '"')                    // \" -> "
      .replace(/\\\\/g, '\\')                  // \\ -> \
      .replace(/^\s*{\s*"message_user"\s*:\s*"([\s\S]*?)"\s*}\s*$/, '$1') // tira {"message_user":"..."}
      .replace(/^"+|"+$/g, '')                 // remove aspas das pontas se sobrarem
      .replace(/\s+/g, ' ')                    // colapsa espaços
      .trim();
  })
  .filter(t => t.length)                        // remove vazios
  .filter((v,i,a) => a.indexOf(v) === i)        // deduplica mantendo a ordem
  .join(', ')
}}

