// Concatena todas as páginas OCR do Mistral em um único campo "full_markdown"
// Funciona com duas situações:
// 1) Você ainda está com o arquivo binário "ocr_output.json" vindo do HTTP Request
// 2) Você já transformou o binário em JSON e tem algo como { pages: [...] } em $json

function getRootFromItem(item) {
  // Caso 2: já está em JSON
  if (item.json && item.json.pages && Array.isArray(item.json.pages)) {
    return item.json;
  }

  // Caso 1: veio como binário "ocr_output.json"
  const bin = item.binary?.['ocr_output.json'];
  if (bin?.data) {
    const raw = Buffer.from(bin.data, 'base64').toString('utf8');
    try {
      const parsed = JSON.parse(raw);
      return parsed;
    } catch (e) {
      throw new Error('Falha ao parsear o JSON do OCR: ' + e.message);
    }
  }

  throw new Error('Não encontrei nem pages no $json nem o binário "ocr_output.json". Verifique o nó anterior.');
}

const out = [];

for (const item of items) {
  const root = getRootFromItem(item);
  const pages = Array.isArray(root.pages) ? root.pages.slice() : [];

  // Ordena pelo index
  pages.sort((a, b) => (a.index ?? 0) - (b.index ?? 0));

  // Monta o markdown completo
  const full = pages
    .map(p => String(p.markdown ?? '').trim())
    .filter(s => s.length > 0)
    .join('\n\n---\n\n');

  out.push({
    json: {
      full_markdown: full,
      page_count: pages.length,
      model: root.model ?? null,
      dimensions: root.dimensions ?? null,
      usage_info: root.usage_info ?? null
    }
  });
}

return out;

