// Code Node genérico para n8n
// Entrada esperada (exemplo):
// {
//   "output": "{ \"acao\": \"registrar_gasto\", \"mensagem\": \"...\", \"tool\": { ... } }",
//   "outra_coisa": "..."
// }
//
// Saída típica para 1 registro:
// {
//   "output_raw": "{...}",         // string original da IA
//   "parsed_output": { ... },      // JSON parseado
//   "acao": "registrar_gasto",     // chaves de nível raiz mescladas
//   "mensagem": "...",
//   "tool": { ... },
//   "outra_coisa": "..."           // campos originais preservados
// }
//
// Saída para múltiplos registros (tool = array) quando acao for
// "registrar_gasto" ou "criar_evento":
// -> vários items, cada um com um "tool" específico, prontos para ir
//    para o HTTP de criação.
//
// Se o JSON for um array na raiz ou valor primitivo, ele vai para
// "parsed_output", mas NÃO é mesclado no root.

const newItems = [];

for (const item of items) {
  const json = item.json ?? {};
  const rawOutput = json.output;

  // Se não tiver output como string, só repassa o item
  if (typeof rawOutput !== 'string') {
    newItems.push(item);
    continue;
  }

  // Tenta limpar possíveis "lixos" (markdown, textos em volta)
  let cleaned = rawOutput.trim();

  // Remove ```json ... ``` se vier assim
  if (cleaned.startsWith('```')) {
    cleaned = cleaned
      .replace(/^```[a-zA-Z]*\n?/, '')
      .replace(/```$/, '')
      .trim();
  }

  // Pega da primeira { até a última } (caso venha texto antes/depois)
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    cleaned = cleaned.slice(firstBrace, lastBrace + 1);
  }

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    // Se não conseguir parsear, devolve erro e o bruto para debug
    newItems.push({
      json: {
        ...json,
        output_raw: rawOutput,
        parse_error: 'JSON inválido em json.output',
        parse_error_detail: String(error),
      },
    });
    continue;
  }

  // Base comum com parsed_output
  const base = {
    ...json,
    output_raw: rawOutput,
    parsed_output: parsed,
  };

  // Se o JSON da raiz NÃO for objeto (for array ou primitivo),
  // não tentamos mesclar; só devolvemos parsed_output
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    delete base.output;
    newItems.push({ json: base });
    continue;
  }

  // parsed é objeto simples na raiz
  // Mescla chaves (acao, mensagem, tool, etc.) no root, sem sobrescrever
  for (const [key, value] of Object.entries(parsed)) {
    if (!(key in base)) {
      base[key] = value;
    }
  }

  // Já não precisamos mais de output bruto original no root
  delete base.output;

  const acao = parsed.acao;
  const tool = parsed.tool;

  const isMultiSupportedAcao =
    acao === 'registrar_gasto' || acao === 'criar_evento';

  // 🔹 Caso especial: múltiplos registros para criação
  // registrar_gasto = lançamentos financeiros
  // criar_evento    = compromissos da agenda
  if (isMultiSupportedAcao && Array.isArray(tool)) {
    for (const toolItem of tool) {
      const cloned = { ...base, tool: toolItem };
      newItems.push({ json: cloned });
    }
    continue;
  }

  // 🔹 Caso padrão: tool não é array OU acao não é de criação multi
  newItems.push({ json: base });
}

return newItems;

